function statLines(u){
  const E = WH_EFFECTS, out = [];
  for(const r of faction().armyRules.concat(detachments().flatMap(detRules))) for(const b of ((D.boxes || {})[DM_KEY.r(r)] || {}).st || []){
    if(!(b.reach ? matches(b.reach, u) : r.needs && matches(r.needs, u))) continue;
    const on = b.on || [], onlyQ = on.length && on.every(([id]) => E.COND[id] && E.COND[id].quoted);
    const when = onlyQ ? FN_IF : on.map(([id, p]) => stCond(id, p, u)).join(' · ');
    for(const [id, p] of b.st){ const f = E.ST[id]; if(!f) continue;
      if(u.stats.every(s => [].concat((s.from || {})[f.stat] || []).join(', ').split(/\s*,\s*/).includes(r.name))) continue;
      const vs = [...new Set(u.stats.map(s => s[f.stat]))], one = !(b.scope || {}).models && vs.length === 1 && (f.inch ? /^\d+"$/ : /^\d+$/).test(String(vs[0]));
      const val = one ? f.stat + ' ' + ((parseInt(vs[0], 10) || 0) + f.add(p)) + (f.inch ? '"' : '') : ((b.scope || {}).models ? (b.scope.models + ' models ') : '') + f.label(p);
      out.push({ rule:r.name, text:(when ? when + ': ' : '') + val }); }
  }
  return out;
}

function stCond(id, p, u){
  const C = WH_EFFECTS.STCOND[id];
  if(!C) return fnCond(id, p, u, '', false);
  return id === 'atStarting' && modelCount(u) === 1 ? 'Lost no wounds (' + C.label(p) + ')' : C.label(p);
}

function naOf(ab, u, units){
  const ss = String(ab.text || '').split('\n').flatMap(l => l.trim().replace(/^-\s+/, '').split(/(?<=[.!?])\s+(?=[A-Z*(])/)).map(x => x.trim()).filter(Boolean);
  if(!ss.length) return undefined;
  const lc = x => x.replace(/\*\*/g, '').replace(/[’‘]/g, "'").toLowerCase();
  if(ss.every(x => NA_LEAD.test(lc(x)))) return u.leads ? undefined : 'Not leading a unit in this list';
  const g = ss.map(x => NA_GEAR.exec(lc(x)));
  if(g.every(Boolean) && g.every(m => m[1] === g[0][1])){
    const gear = g[0][1].split(/,? and |, /).map(x => x.replace(/^(?:an?|the) /, '').trim());
    const wn = [].concat(u.ranged || [], u.melee || []).flatMap(w => [w.name, w.group]).filter(Boolean).map(x => String(x).toLowerCase());
    // (GW's words for them, as its text has them: "Needs a thundershock spear and a bellatus reaper chainsword")
    const words = /^if this model is equipped with (.+?), /i.exec(ss[0].replace(/\*\*/g, ''))[1];
    return gear.every(x => wn.some(n => n.startsWith(x))) ? undefined : 'Needs ' + words + ': not this loadout'; }
  const k = ss.map(x => NA_KW.exec(x));
  if(k.every(Boolean) && k.every(m => m[1] === k[0][1])){
    const kw = k[0][1].trim(), has = x => (x.kw || []).some(y => String(y).replace(/^Faction: /, '').toLowerCase() === kw.toLowerCase());
    return (units || []).some(has) ? undefined : 'No ' + kw + ' in this list'; }
  return undefined;
}

function statOf(src, us, V){
  if(src.type !== 'rule') return [];
  const out = [];
  for(const u of sentencesOf(src.text)){
    const n = norm(u.s), st = [];
    for(const [id, f] of Object.entries(E.ST)) for(const re of f.pats){ const m = re.exec(n); if(m) st.push([id, +m[1]]); }
    if(!st.length) continue;
    const box = { quote:u.s, st, on:condsOf(V, u.s, '', { stat:true, inherit:true }) };
    const r = reachOf(V, u.s) || (u.prevS ? reachOf(V, u.prevS) : null);
    if(r) box.reach = r;
    const mk = ST_SCOPE.exec(u.s); if(mk) box.scope = { models:mk[1].trim() };
    out.push(box);
  }
  return out;
}

const cpNoteOf = effect => { const out = [];
  for(const l of String(effect || '').split('\n')){ let m; if((m = CP_OR.exec(l.trim()))) out.push('Or: +' + m[1] + 'CP'); else if((m = CP_OPT.exec(l.trim()))) out.push(m[1].trim() + ' +' + m[2] + 'CP'); }
  return out.length ? out.join(' · ') : undefined; };

function kwNoteOf(u, faction, why, grants, cats) {
    const parts = partsOf(u, faction), segs = [], kwN = new Set((u.kw || []).map(n)), said = new Set();
    // ("instead": the ability's sentence, the keywords it gives and takes)
    const inst = [];
    for (const ab of u.abilities || []) for (const sen of String(ab.text || '').split(/(?<=[.!?])\s+/)) { const m = INSTEAD.exec(sen); if (m) inst.push({ ab, sen, give:'Faction: ' + TC(m[1]), take:'Faction: ' + TC(m[2]) }); }
    if (u.leads && parts.length > 1 && parts.every(p => p.page)) {
      const names = parts.map((p, i) => nameKeyword(p, (cats || [])[i], faction));
      const kwOf = (p, i) => new Set(p.page.unitKeywords.map(n).concat(p.page.factionKeywords.map(k => n('Faction: ' + k)), names[i] && !names[i].undeclared ? [n(names[i].kw)] : []));
      const first = kwOf(parts[0], 0), only = new Set(Object.keys(u.kwOnly || {}).map(n));
      // (the first part's ability that gives it another Faction keyword "instead": the one it takes is not the first's)
      for (const x of inst) if (!x.ab.who || n(x.ab.who) === n(parts[0].name)) first.delete(n(x.take));
      const extra = [];
      parts.slice(1).forEach((p, j) => { const ks = kwOf(p, j + 1); for (const k of (u.kw || []).filter(k => ks.has(n(k))).sort()) if (!first.has(n(k)) && !only.has(n(k)) && !extra.includes(k)) extra.push(k); });
      if (extra.length) { segs.push(extra.join(', ') + (extra.length > 1 ? ' come' : ' comes') + ' from the ' + ((u.also || []).length ? 'combined unit' : (u.support ? 'supported ' : 'led ') + u.leads)); extra.forEach(k => said.add(n(k))); }
    }
    // a rule's
    const own = new Set((u.abilities || []).filter(x => /\b(Enhancement|Upgrade)\b/.test(x.tag || '')).map(x => x.name));
    const by = new Map();
    for (const k of u.kw || []) { const r = ((why || {}).kw || {})[k]; if (!r || r === 'Warlord' || said.has(n(k))) continue;
      const g = (grants || []).find(x => /keyword/.test(x.type) && n(x.grants) === n(k) && (x.option === r || String(x.rule).split(' · ').pop() === r));
      const ab = own.has(r) ? (u.abilities || []).find(x => x.name === r) : null;
      const sen = ab ? String(ab.text || '').split(/(?<=[.!?])\s+/).find(t => new RegExp('\\*\\*' + k.toUpperCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\*\\* keyword').test(t)) : null;
      if (!(u.leads || ab || (g && g.to === null))) continue;
      const q = sen || (g && g.text); if (!q) continue;
      if (!by.has(r)) by.set(r, { ks:[], q }); by.get(r).ks.push(k); said.add(n(k)); }
    for (const [r, x] of by) segs.push(x.ks.join(', ') + (x.ks.length > 1 ? ' come' : ' comes') + ' from ' + r + ' (“' + plainQ(x.q) + '”)');
    for (const x of inst) if (kwN.has(n(x.give)) && !said.has(n(x.give))) { segs.push(x.give + ' comes from ' + x.ab.name + ' (“' + plainQ(x.sen) + '”)'); said.add(n(x.give)); }
    return segs.length ? segs.join('; ') + '.' : undefined;
  }

function srcNoteOf(u, faction) {
    const parts = partsOf(u, faction), pn = x => n(String(x).replace(/ ×\d+$/, ''));
    for (const m of [...new Set((u.stats || []).map(r => String(r.name).replace(/ ×\d+$/, '')))]) {
      if (parts.some(p => pn(p.name) === pn(m))) continue;
      const M = pageFor(faction, m); if (!M || parts.some(p => p.page && (p.page.file === M.file || (p.page.profiles || []).some(x => x.name && pn(x.name) === pn(m))))) continue;
      return { at:m, note:'Wahapedia: its own ' + ((M.unitKeywords || []).some(k => n(k) === n('EPIC HERO')) ? 'EPIC HERO ' : '') + 'datasheet; BSData and New Recruit: in this unit' };
    }
    return undefined;
  }

function noteSegments(note) {
  const out = []; let t = String(note || '');
  while (t.length) {
    const L = LABELS_LONG.find(l => t.startsWith(l + ': '));
    if (!L) return { bad: t.slice(0, 90) };
    t = t.slice(L.length + 2);
    const qs = []; let m;
    while ((m = /^“([^”]+)”/.exec(t))) { qs.push(m[1]); t = t.slice(m[0].length); if (t.startsWith(' ')) t = t.slice(1); else break; }
    if (!qs.length) return { bad: L + ': ' + t.slice(0, 80) };
    out.push({ label: L, kind: NOTE_LABELS[L], qs });
  }
  return out.length ? { segs: out } : { bad: '(empty)' };
}
